import { describe, expect, test } from "bun:test"
import { tailscaleDnsmasqConfigRender } from "./tailscaleDnsmasqConfigRender.js"

describe("tailscaleDnsmasqConfigRender", () => {
  test("renders exact-host answers with upstream forwarding", () => {
    const result = tailscaleDnsmasqConfigRender({
      nodeAddress: "100.122.200.114",
      hostnames: ["b.wonder1.de", "a.wonder1.de", "a.wonder1.de"],
      upstreamResolvers: ["1.1.1.1", "8.8.8.8"],
    })
    expect(result.success).toBe(true)
    if (!result.success) return
    expect(result.data).toBe(
      [
        "# Generated by project-registry private DNS (split-horizon dnsmasq). Do not hand-edit.",
        "# Private A answers for the approved private hostnames only; AAAA returns NODATA (host-record + local).",
        "# Public passthroughs stay public: most-specific server=/name/upstream forwards",
        "# keep those exact names on upstream resolvers.",
        "# Everything else forwards upstream; never widen hostnames to whole zones.",
        "# NOTE (DNS-01): Caddy tls dns challenges must use explicit public resolvers, never this listener.",
        "port=53",
        "interface=tailscale0",
        "bind-interfaces",
        "listen-address=100.122.200.114,127.0.0.1",
        "no-resolv",
        "bogus-priv",
        "domain-needed",
        "server=1.1.1.1",
        "server=8.8.8.8",
        "host-record=a.wonder1.de,100.122.200.114",
        "local=/a.wonder1.de/",
        "host-record=b.wonder1.de,100.122.200.114",
        "local=/b.wonder1.de/",
        "",
      ].join("\n"),
    )
  })

  test("emits per-host lines only and forwards passthroughs upstream", () => {
    const result = tailscaleDnsmasqConfigRender({
      nodeAddress: "100.122.200.114",
      hostnames: ["a.wonder1.de"],
      upstreamResolvers: ["1.1.1.1"],
      listenLoopback: false,
      publicPassthroughs: ["assets.wonder1.de", "a.wonder1.de"],
    })
    expect(result.success).toBe(true)
    if (!result.success) return
    expect(result.data).toContain("listen-address=100.122.200.114\n")
    expect(result.data).not.toContain("127.0.0.1")
    expect(result.data).toContain("server=/assets.wonder1.de/1.1.1.1\n")
    expect(result.data).not.toContain("server=/wonder1.de/")
    expect(result.data).not.toContain("local=/wonder1.de/")
    const hostLines = result.data.split("\n").filter((line) => line.startsWith("local=/"))
    expect(hostLines).toEqual(["local=/a.wonder1.de/"])
  })

  test("rejects wildcards, malformed hosts, and missing upstreams", () => {
    const base = { nodeAddress: "100.122.200.114", hostnames: ["a.wonder1.de"], upstreamResolvers: ["1.1.1.1"] }
    expect(tailscaleDnsmasqConfigRender({ ...base, hostnames: ["*.wonder1.de"] }).success).toBe(false)
    expect(tailscaleDnsmasqConfigRender({ ...base, hostnames: ["solo"] }).success).toBe(false)
    expect(tailscaleDnsmasqConfigRender({ ...base, upstreamResolvers: [] }).success).toBe(false)
    expect(tailscaleDnsmasqConfigRender({ ...base, nodeAddress: "not-an-ip" }).success).toBe(false)
    expect(tailscaleDnsmasqConfigRender({ ...base, publicPassthroughs: ["*.wonder1.de"] }).success).toBe(false)
    expect(tailscaleDnsmasqConfigRender(null).success).toBe(false)
  })
})
